CREATE TABLE el_library_books(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,title TEXT NOT NULL,isbn TEXT NOT NULL DEFAULT '',author TEXT NOT NULL,category TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),is_demo INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,UNIQUE(org_id,id));
CREATE TABLE el_library_copies(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,book_id TEXT NOT NULL,barcode TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'available' CHECK(status IN ('available','loaned','maintenance','lost','retired')),is_demo INTEGER NOT NULL DEFAULT 0,UNIQUE(org_id,id),UNIQUE(org_id,barcode),FOREIGN KEY(org_id,book_id) REFERENCES el_library_books(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE TABLE el_borrow_records(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,copy_id TEXT NOT NULL,student_id TEXT NOT NULL,borrowed_on TEXT NOT NULL,due_on TEXT NOT NULL,returned_on TEXT,late_days INTEGER NOT NULL DEFAULT 0 CHECK(late_days>=0),daily_penalty INTEGER NOT NULL DEFAULT 0 CHECK(daily_penalty>=0),penalty_total INTEGER NOT NULL DEFAULT 0 CHECK(penalty_total>=0),issued_by TEXT NOT NULL,returned_by TEXT,notes TEXT NOT NULL DEFAULT '',is_demo INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,CHECK(due_on>=borrowed_on),CHECK(returned_on IS NULL OR returned_on>=borrowed_on),UNIQUE(org_id,id),FOREIGN KEY(org_id,copy_id) REFERENCES el_library_copies(org_id,id),FOREIGN KEY(org_id,student_id) REFERENCES el_students(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,issued_by) REFERENCES el_memberships(org_id,user_id));
CREATE UNIQUE INDEX el_one_active_borrow ON el_borrow_records(copy_id) WHERE returned_on IS NULL;
CREATE TRIGGER el_borrow_insert_guard BEFORE INSERT ON el_borrow_records BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_library_copies co JOIN el_library_books b ON b.id=co.book_id JOIN el_students s ON s.org_id=co.org_id AND s.id=NEW.student_id WHERE co.id=NEW.copy_id AND co.org_id=NEW.org_id AND co.branch_id=NEW.branch_id AND s.branch_id=NEW.branch_id AND s.status='active' AND co.status='available' AND b.status='active') THEN RAISE(ABORT,'Library copy or borrower is unavailable') END;END;
CREATE TRIGGER el_borrow_checkout AFTER INSERT ON el_borrow_records BEGIN UPDATE el_library_copies SET status='loaned' WHERE id=NEW.copy_id;END;
CREATE TRIGGER el_borrow_return_guard BEFORE UPDATE ON el_borrow_records BEGIN SELECT CASE WHEN OLD.returned_on IS NOT NULL OR NEW.returned_on IS NULL OR NEW.copy_id<>OLD.copy_id OR NEW.student_id<>OLD.student_id OR NEW.due_on<>OLD.due_on OR NEW.borrowed_on<>OLD.borrowed_on OR NEW.daily_penalty<>OLD.daily_penalty THEN RAISE(ABORT,'Library return requires an active immutable loan') END;END;
CREATE TRIGGER el_borrow_return AFTER UPDATE ON el_borrow_records BEGIN UPDATE el_library_copies SET status='available' WHERE id=NEW.copy_id;END;
CREATE TABLE el_library_reservations(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,book_id TEXT NOT NULL,student_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'waiting' CHECK(status IN ('waiting','fulfilled','cancelled')),borrow_id TEXT,is_demo INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,UNIQUE(org_id,id),FOREIGN KEY(org_id,book_id) REFERENCES el_library_books(org_id,id),FOREIGN KEY(org_id,student_id) REFERENCES el_students(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,borrow_id) REFERENCES el_borrow_records(org_id,id));
CREATE UNIQUE INDEX el_library_reservation_one ON el_library_reservations(org_id,branch_id,book_id,student_id) WHERE status='waiting';
CREATE INDEX el_library_catalog ON el_library_books(org_id,status,title);
CREATE INDEX el_library_copies_branch ON el_library_copies(org_id,branch_id,book_id,status);
CREATE INDEX el_borrow_student ON el_borrow_records(org_id,student_id,returned_on,due_on);
CREATE INDEX el_borrow_branch ON el_borrow_records(org_id,branch_id,returned_on,due_on);
CREATE INDEX el_library_queue ON el_library_reservations(org_id,branch_id,book_id,status,created_at);
CREATE TRIGGER el_library_queue_guard BEFORE INSERT ON el_borrow_records BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM el_library_reservations r JOIN el_library_copies c ON c.book_id=r.book_id AND c.branch_id=r.branch_id WHERE c.id=NEW.copy_id AND r.org_id=NEW.org_id AND r.status='waiting' AND r.id=(SELECT id FROM el_library_reservations q WHERE q.org_id=r.org_id AND q.branch_id=r.branch_id AND q.book_id=r.book_id AND q.status='waiting' ORDER BY q.created_at,q.id LIMIT 1) AND r.student_id<>NEW.student_id) THEN RAISE(ABORT,'Library copy is reserved for another student') END;END;
CREATE TRIGGER el_library_archive_guard BEFORE UPDATE ON el_library_books WHEN NEW.status='archived' AND EXISTS(SELECT 1 FROM el_borrow_records r JOIN el_library_copies co ON co.id=r.copy_id WHERE co.book_id=OLD.id AND r.returned_on IS NULL) BEGIN SELECT RAISE(ABORT,'Return outstanding copies before archiving');END;
